-- PostgreSQL schema; existing SQLite files are never modified.
CREATE TABLE IF NOT EXISTS users (
 id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL,
 password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('student','parent','teacher','admin')),
 avatar TEXT NOT NULL DEFAULT 'orange', created_at BIGINT NOT NULL
);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS relations (adult_id INTEGER NOT NULL REFERENCES users(id), student_id INTEGER NOT NULL REFERENCES users(id), PRIMARY KEY(adult_id,student_id));
CREATE TABLE IF NOT EXISTS courses (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL, subject TEXT NOT NULL DEFAULT 'Matematika', color TEXT NOT NULL DEFAULT 'orange');
CREATE TABLE IF NOT EXISTS modules (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, course_id INTEGER NOT NULL REFERENCES courses(id), title TEXT NOT NULL, position INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS lessons (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, module_id INTEGER NOT NULL REFERENCES modules(id), title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', slides_json TEXT NOT NULL, lab_type TEXT, position INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS progress (user_id INTEGER NOT NULL REFERENCES users(id), lesson_id INTEGER NOT NULL REFERENCES lessons(id), slide INTEGER NOT NULL DEFAULT 0, completed INTEGER NOT NULL DEFAULT 0, updated_at BIGINT NOT NULL, PRIMARY KEY(user_id,lesson_id));
CREATE TABLE IF NOT EXISTS assessments (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, lesson_id INTEGER REFERENCES lessons(id), module_id INTEGER NOT NULL REFERENCES modules(id), title TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('test','exam')), duration_seconds INTEGER NOT NULL DEFAULT 600);
CREATE TABLE IF NOT EXISTS questions (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, assessment_id INTEGER NOT NULL REFERENCES assessments(id), prompt TEXT NOT NULL, options_json TEXT NOT NULL, correct_index INTEGER NOT NULL, explanation TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attempts (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), assessment_id INTEGER NOT NULL REFERENCES assessments(id), started_at BIGINT NOT NULL, deadline BIGINT NOT NULL, submitted_at BIGINT, questions_json TEXT NOT NULL, answers_json TEXT, score INTEGER, feedback_json TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_open_attempt ON attempts(user_id,assessment_id) WHERE submitted_at IS NULL;
CREATE TABLE IF NOT EXISTS rewards (user_id INTEGER NOT NULL REFERENCES users(id), source TEXT NOT NULL, xp INTEGER NOT NULL, created_at BIGINT NOT NULL, PRIMARY KEY(user_id,source));
CREATE TABLE IF NOT EXISTS focus_sessions (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), lesson_id INTEGER NOT NULL REFERENCES lessons(id), goal TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('running','paused','completed')), phase TEXT NOT NULL CHECK(phase IN ('study','break')), deadline BIGINT, remaining_ms INTEGER NOT NULL, active_seconds INTEGER NOT NULL DEFAULT 0, heartbeat_at BIGINT, heartbeat_active INTEGER NOT NULL DEFAULT 0, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, finished_at BIGINT);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_focus ON focus_sessions(user_id) WHERE state IN ('running','paused');
CREATE TABLE IF NOT EXISTS labs (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), lesson_id INTEGER NOT NULL REFERENCES lessons(id), numerator INTEGER NOT NULL, denominator INTEGER NOT NULL, conclusion TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','submitted')), updated_at BIGINT NOT NULL, UNIQUE(user_id,lesson_id));
CREATE TABLE IF NOT EXISTS support (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES users(id), lesson_id INTEGER NOT NULL REFERENCES lessons(id), question TEXT NOT NULL, answer TEXT, teacher_id INTEGER REFERENCES users(id), created_at BIGINT NOT NULL, answered_at BIGINT);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at BIGINT NOT NULL);

CREATE UNIQUE INDEX IF NOT EXISTS users_email_lower_idx ON users(LOWER(email));
CREATE TABLE IF NOT EXISTS lesson_content_versions (lesson_id INTEGER PRIMARY KEY REFERENCES lessons(id) ON DELETE CASCADE, version INTEGER NOT NULL);
